def fizzbuzz(n):
    """
    FizzBuzz function returns 'Fizz' if n is divisible by 3,
    'Buzz' if n is divisible by 5, 'FizzBuzz' if n is divisible by 15,
    and the number itself as a string otherwise.
    """
    if n % 15 == 0:
        return "FizzBuzz"
    elif n % 3 == 0:
        return "Fizz"
    elif n % 5 == 0:
        return "Buzz"
    else:
        return str(n)


